materials.fragmentShader:
varying float vH;varying vec3 vP;uniform float uMin,uMax,uTime,uContour,uInt;
void main(){
 float t=clamp((vH-uMin)/(uMax-uMin),0.,1.);
 vec3 lo=vec3(0.02,0.30,1.0),mid=vec3(0.05,0.95,1.0),hi=vec3(0.85,1.0,1.0);
 vec3 col=t<0.5?mix(lo,mid,t*2.):mix(mid,hi,(t-0.5)*2.);
 vec2 g=vP.xz/10.; vec2 gd=abs(fract(g+0.5)-0.5)/fwidth(g);
 float grid=1.-min(min(gd.x,gd.y),1.);
 vec2 g2=vP.xz; vec2 gd2=abs(fract(g2+0.5)-0.5)/fwidth(g2);
 float fine=(1.-min(min(gd2.x,gd2.y),1.))*0.18;
 float f=fract(vH/uInt); float fw=fwidth(vH/uInt);
 float con=(1.-smoothstep(0.,max(fw*1.4,0.001),min(f,1.-f)))*uContour;
 float sweep=exp(-abs(vP.x-(mod(uTime*18.,140.)-70.))*0.35);
 float edge=smoothstep(49.0,49.8,max(abs(vP.x),abs(vP.z)));
 float a=0.10+0.07*t+grid*0.55+fine+con*0.65+sweep*0.45+edge*0.8;
 vec3 c=col*(0.8+grid*0.7+con*0.9)+vec3(sweep*0.5)+vec3(0.1,0.3,0.4)*edge;
 gl_FragColor=vec4(c,clamp(a,0.,1.));
}
